-- 0007: certificate courses (server-graded), moderated study groups, push helpers. Idempotent. Run after 0006.
-- Course content and answer keys are loaded from supabase/seed/courses.sql (generated by tools/build_courses.py).

-- =====================================================================================
-- 1. Courses and certificates
-- =====================================================================================
create table if not exists public.courses (
  slug         text primary key check (slug ~ '^[a-z0-9-]{3,40}$'),
  title        text not null,
  level        text not null check (level in ('all','secondary','university')),
  pass_mark    smallint not null default 70 check (pass_mark between 50 and 100),
  lesson_count smallint not null default 0,
  quiz_count   smallint not null default 0,
  active       boolean not null default true,
  updated_at   timestamptz not null default now()
);
create table if not exists public.course_lessons (
  course    text not null references public.courses(slug) on delete cascade,
  lesson_id text not null,
  position  smallint not null,
  primary key (course, lesson_id)
);
-- answer keys: RLS on and NO policy, so students can never read them; grading runs inside submit_course_quiz
create table if not exists public.course_keys (
  course text not null references public.courses(slug) on delete cascade,
  qid    text not null,
  answer smallint not null check (answer between 0 and 3),
  why    text not null,
  primary key (course, qid)
);
create table if not exists public.course_progress (
  user_id      uuid not null references public.profiles(id) on delete cascade,
  course       text not null references public.courses(slug) on delete cascade,
  lessons_done text[] not null default '{}',
  best_score   smallint,
  updated_at   timestamptz not null default now(),
  primary key (user_id, course)
);
create table if not exists public.course_attempts (
  id         bigint generated always as identity primary key,
  user_id    uuid not null references public.profiles(id) on delete cascade,
  course     text not null references public.courses(slug) on delete cascade,
  score      smallint not null,
  created_at timestamptz not null default now()
);
create index if not exists course_attempts_user on public.course_attempts (user_id, course, created_at desc);
create table if not exists public.certificates (
  id          uuid primary key default gen_random_uuid(),
  code        text not null unique,
  user_id     uuid not null references public.profiles(id) on delete cascade,
  course      text not null references public.courses(slug),
  score       smallint not null,
  holder_name text not null,
  issued_at   timestamptz not null default now(),
  unique (user_id, course)
);
alter table public.courses         enable row level security;
alter table public.course_lessons  enable row level security;
alter table public.course_keys     enable row level security;
alter table public.course_progress enable row level security;
alter table public.course_attempts enable row level security;
alter table public.certificates    enable row level security;
revoke all on public.course_keys, public.course_attempts from anon, authenticated;
revoke insert, update, delete on public.courses, public.course_lessons, public.course_progress, public.certificates from anon, authenticated;
drop policy if exists courses_read on public.courses;
create policy courses_read on public.courses for select using (active);
drop policy if exists lessons_read on public.course_lessons;
create policy lessons_read on public.course_lessons for select to authenticated using (true);
drop policy if exists cprog_own on public.course_progress;
create policy cprog_own on public.course_progress for select to authenticated using (user_id = auth.uid());
drop policy if exists cert_own on public.certificates;
create policy cert_own on public.certificates for select to authenticated using (user_id = auth.uid());
grant select on public.courses to anon;

create or replace function public.mark_lesson(p_course text, p_lesson text) returns void
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  if not exists (select 1 from public.course_lessons l join public.courses c on c.slug = l.course
                 where l.course = p_course and l.lesson_id = p_lesson and c.active) then raise exception 'unknown lesson'; end if;
  insert into public.course_progress(user_id, course, lessons_done) values (auth.uid(), p_course, array[p_lesson])
  on conflict (user_id, course) do update
    set lessons_done = case when p_lesson = any(public.course_progress.lessons_done) then public.course_progress.lessons_done
                            else array_append(public.course_progress.lessons_done, p_lesson) end,
        updated_at = now();
end $$;
revoke all on function public.mark_lesson(text,text) from public, anon;
grant execute on function public.mark_lesson(text,text) to authenticated;

-- grades on the server. p_answers is {"q1":2,"q2":0,...}. Five attempts per course per day.
create or replace function public.submit_course_quiz(p_course text, p_answers jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare c record; done int; total int; ok int := 0; sc int; passed boolean; cert text; nm text; rev jsonb := '[]'::jsonb; k record; given int;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  select * into c from public.courses where slug = p_course and active;
  if not found then raise exception 'unknown course'; end if;
  select count(*) into done from public.course_lessons l
    where l.course = p_course and l.lesson_id = any(coalesce((select lessons_done from public.course_progress where user_id = auth.uid() and course = p_course), '{}'));
  if done < c.lesson_count then raise exception 'Finish all % lessons before the quiz.', c.lesson_count; end if;
  if (select count(*) from public.course_attempts where user_id = auth.uid() and course = p_course and created_at > now() - interval '1 day') >= 5 then
    raise exception 'You have used 5 attempts today. Review the lessons and try again tomorrow.'; end if;
  select count(*) into total from public.course_keys where course = p_course;
  if total = 0 then raise exception 'This course quiz is not available yet.'; end if;
  for k in select * from public.course_keys where course = p_course order by qid loop
    given := case when jsonb_typeof(p_answers -> k.qid) = 'number' then (p_answers ->> k.qid)::int else null end;
    if given is not distinct from k.answer then ok := ok + 1;
      rev := rev || jsonb_build_array(jsonb_build_object('qid', k.qid, 'ok', true));
    else rev := rev || jsonb_build_array(jsonb_build_object('qid', k.qid, 'ok', false, 'why', k.why)); end if;
  end loop;
  sc := round(100.0 * ok / total); passed := sc >= c.pass_mark;
  insert into public.course_attempts(user_id, course, score) values (auth.uid(), p_course, sc);
  update public.course_progress set best_score = greatest(coalesce(best_score, 0), sc), updated_at = now()
    where user_id = auth.uid() and course = p_course;
  if passed then
    select code into cert from public.certificates where user_id = auth.uid() and course = p_course;
    if cert is null then
      select first_name || ' ' || surname into nm from public.profiles where id = auth.uid();
      cert := upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 12));
      insert into public.certificates(code, user_id, course, score, holder_name) values (cert, auth.uid(), p_course, sc, nm);
    end if;
  end if;
  return jsonb_build_object('score', sc, 'passed', passed, 'correct', ok, 'total', total, 'pass_mark', c.pass_mark, 'code', cert, 'review', rev);
end $$;
revoke all on function public.submit_course_quiz(text,jsonb) from public, anon;
grant execute on function public.submit_course_quiz(text,jsonb) to authenticated;

-- public check used by the verification page: a code returns the holder, course, score and date, nothing else
create or replace function public.verify_certificate(p_code text)
returns table (holder_name text, course_title text, score smallint, issued_at timestamptz)
language sql stable security definer set search_path = public as $$
  select ce.holder_name, c.title, ce.score, ce.issued_at
  from public.certificates ce join public.courses c on c.slug = ce.course
  where ce.code = upper(regexp_replace(trim(p_code), '[^A-Za-z0-9]', '', 'g')) $$;
revoke all on function public.verify_certificate(text) from public;
grant execute on function public.verify_certificate(text) to anon, authenticated;

-- =====================================================================================
-- 2. Study groups with safeguards
--    class group  : one class (students of that class; its teachers supervise)
--    school group : one school (students of that school)
--    institution  : university students of the same institution and country
--    No open public groups. A school's staff can always read their school's groups.
-- =====================================================================================
create table if not exists public.study_groups (
  id              uuid primary key default gen_random_uuid(),
  name            text not null check (length(name) between 3 and 60),
  description     text check (length(description) <= 300),
  scope           text not null check (scope in ('class','school','institution')),
  school_id       uuid references public.schools(id) on delete cascade,
  class_id        uuid references public.classes(id) on delete cascade,
  country_code    text references public.countries(code),
  institution_key text,
  institution     text,
  created_by      uuid references public.profiles(id) on delete set null,
  archived        boolean not null default false,
  created_at      timestamptz not null default now(),
  check ((scope = 'class' and class_id is not null and school_id is not null)
      or (scope = 'school' and school_id is not null and class_id is null)
      or (scope = 'institution' and institution_key is not null and country_code is not null and school_id is null))
);
create table if not exists public.group_members (
  group_id    uuid not null references public.study_groups(id) on delete cascade,
  user_id     uuid not null references public.profiles(id) on delete cascade,
  role        text not null default 'member' check (role in ('member','mod')),
  joined_at   timestamptz not null default now(),
  muted_until timestamptz,
  primary key (group_id, user_id)
);
create index if not exists group_members_user on public.group_members (user_id);
create table if not exists public.group_posts (
  id            bigint generated always as identity primary key,
  group_id      uuid not null references public.study_groups(id) on delete cascade,
  author_id     uuid not null references public.profiles(id) on delete cascade,
  body          text not null check (length(body) between 1 and 1000),
  reply_to      bigint references public.group_posts(id) on delete set null,
  hidden        boolean not null default false,
  hidden_reason text,
  created_at    timestamptz not null default now()
);
create index if not exists group_posts_feed on public.group_posts (group_id, id desc);
create table if not exists public.post_reports (
  post_id    bigint not null references public.group_posts(id) on delete cascade,
  reporter_id uuid not null references public.profiles(id) on delete cascade,
  reason     text not null check (length(reason) between 3 and 300),
  created_at timestamptz not null default now(),
  primary key (post_id, reporter_id)
);
create table if not exists public.mod_actions (
  id        bigint generated always as identity primary key,
  group_id  uuid references public.study_groups(id) on delete cascade,
  post_id   bigint,
  actor_id  uuid references public.profiles(id) on delete set null,
  target_id uuid,
  action    text not null,
  created_at timestamptz not null default now()
);
alter table public.study_groups  enable row level security;
alter table public.group_members enable row level security;
alter table public.group_posts   enable row level security;
alter table public.post_reports  enable row level security;
alter table public.mod_actions   enable row level security;
revoke insert, update, delete on public.study_groups, public.group_members, public.group_posts, public.post_reports, public.mod_actions from anon, authenticated;
revoke all on public.post_reports from anon, authenticated;

create or replace function public._inst_key(s text) returns text language sql immutable as
$$ select nullif(lower(regexp_replace(trim(coalesce(s,'')), '\s+', ' ', 'g')), '') $$;

create or replace function public.in_group(gid uuid) returns boolean language sql stable security definer set search_path = public as
$$ select exists (select 1 from public.group_members where group_id = gid and user_id = auth.uid()) $$;

-- who may read everything in a group and moderate it: platform admin, a group mod, and the school's staff
create or replace function public.can_moderate_group(gid uuid) returns boolean language sql stable security definer set search_path = public as $$
  select coalesce(public.is_platform_admin(), false)
      or exists (select 1 from public.group_members where group_id = gid and user_id = auth.uid() and role = 'mod')
      or exists (select 1 from public.study_groups g where g.id = gid and g.school_id is not null
                   and (case when g.class_id is not null then public.teaches_class(g.class_id)
                             else public.is_school_admin_of(g.school_id)
                                  or exists (select 1 from public.profiles p where p.id = auth.uid() and p.school_id = g.school_id and p.role in ('teacher','subject_teacher')) end)) $$;

-- may the caller join/see this group as a member? (students only for class/school/institution scope)
create or replace function public.group_eligible(gid uuid) returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.study_groups g join public.profiles p on p.id = auth.uid()
    where g.id = gid and not g.archived and (
         (p.role = 'student' and g.scope = 'class'  and g.class_id = p.class_id)
      or (p.role = 'student' and g.scope = 'school' and g.school_id = p.school_id)
      or (p.role = 'student' and p.level = 'university' and g.scope = 'institution'
          and g.country_code = p.country_code and g.institution_key = public._inst_key(p.institution)))) $$;

drop policy if exists sg_read on public.study_groups;
create policy sg_read on public.study_groups for select to authenticated
  using (public.in_group(id) or public.can_moderate_group(id) or public.group_eligible(id));
drop policy if exists gm_read on public.group_members;
create policy gm_read on public.group_members for select to authenticated
  using (user_id = auth.uid() or public.can_moderate_group(group_id));
drop policy if exists gp_read on public.group_posts;
create policy gp_read on public.group_posts for select to authenticated
  using ((public.in_group(group_id) and not hidden) or public.can_moderate_group(group_id));
drop policy if exists ma_read on public.mod_actions;
create policy ma_read on public.mod_actions for select to authenticated using (public.can_moderate_group(group_id));

-- text rules for anything students write in groups: no links, e-mail addresses or phone numbers
create or replace function public._clean_text(t text) returns text language plpgsql immutable as $$
declare s text := trim(coalesce(t, ''));
begin
  if s ~* '(https?://|www\.|\m[a-z0-9-]+\.(com|net|org|io|me|co|ly|app|xyz)\M)' then raise exception 'Links are not allowed in groups.'; end if;
  if s ~ '[^\s@]+@[^\s@]+' then raise exception 'Do not share e-mail addresses in groups.'; end if;
  if regexp_replace(s, '[^0-9]', '', 'g') ~ '[0-9]{9,}' and s ~ '(\d[\s.\-]?){9,}' then raise exception 'Do not share phone numbers in groups.'; end if;
  return s;
end $$;

create or replace function public.create_group(p_name text, p_desc text, p_scope text, p_class uuid default null) returns uuid
language plpgsql security definer set search_path = public as $$
declare p record; gid uuid; nm text := public._clean_text(p_name); ds text := nullif(public._clean_text(p_desc), '');
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  select * into p from public.profiles where id = auth.uid();
  if length(nm) < 3 then raise exception 'Give the group a name of at least 3 characters.'; end if;
  if (select count(*) from public.study_groups where created_by = auth.uid() and not archived) >= 3 then raise exception 'You can run up to 3 groups.'; end if;
  if p.role = 'student' then
    if p_scope = 'class' and p.class_id is not null then
      insert into public.study_groups(name, description, scope, school_id, class_id, created_by) values (nm, ds, 'class', p.school_id, p.class_id, auth.uid()) returning id into gid;
    elsif p_scope = 'school' and p.school_id is not null then
      insert into public.study_groups(name, description, scope, school_id, created_by) values (nm, ds, 'school', p.school_id, auth.uid()) returning id into gid;
    elsif p_scope = 'institution' and p.level = 'university' and public._inst_key(p.institution) is not null then
      insert into public.study_groups(name, description, scope, country_code, institution_key, institution, created_by)
        values (nm, ds, 'institution', p.country_code, public._inst_key(p.institution), left(trim(p.institution), 120), auth.uid()) returning id into gid;
    else raise exception 'You cannot create that kind of group. Set your class or institution first.'; end if;
  elsif p.role in ('teacher','subject_teacher','school_admin') then
    if p_scope = 'class' and p_class is not null and public.teaches_class(p_class) then
      insert into public.study_groups(name, description, scope, school_id, class_id, created_by) values (nm, ds, 'class', public.class_school(p_class), p_class, auth.uid()) returning id into gid;
    elsif p_scope = 'school' and p.school_id is not null then
      insert into public.study_groups(name, description, scope, school_id, created_by) values (nm, ds, 'school', p.school_id, auth.uid()) returning id into gid;
    else raise exception 'You cannot create that kind of group.'; end if;
  else raise exception 'You cannot create groups.'; end if;
  insert into public.group_members(group_id, user_id, role) values (gid, auth.uid(), 'mod');
  return gid;
end $$;

create or replace function public.join_group(gid uuid) returns void language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  if not public.group_eligible(gid) then raise exception 'You cannot join this group.'; end if;
  if (select count(*) from public.group_members where user_id = auth.uid()) >= 12 then raise exception 'You can be in up to 12 groups.'; end if;
  insert into public.group_members(group_id, user_id) values (gid, auth.uid()) on conflict do nothing;
end $$;

create or replace function public.leave_group(gid uuid) returns void language plpgsql security definer set search_path = public as $$
begin
  delete from public.group_members where group_id = gid and user_id = auth.uid();
end $$;

create or replace function public.post_to_group(gid uuid, p_body text, p_reply bigint default null) returns bigint
language plpgsql security definer set search_path = public as $$
declare m record; b text; pid bigint;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  select gm.* into m from public.group_members gm join public.study_groups g on g.id = gm.group_id and not g.archived
    where gm.group_id = gid and gm.user_id = auth.uid();
  if not found then raise exception 'Join the group to post.'; end if;
  if m.muted_until is not null and m.muted_until > now() then raise exception 'You are muted in this group until %.', to_char(m.muted_until, 'YYYY-MM-DD HH24:MI'); end if;
  b := public._clean_text(p_body);
  if length(b) < 1 then raise exception 'Write something first.'; end if;
  if length(b) > 1000 then raise exception 'Posts can be up to 1000 characters.'; end if;
  if (select count(*) from public.group_posts where author_id = auth.uid() and created_at > now() - interval '1 minute') >= 6 then raise exception 'Slow down a little.'; end if;
  if (select count(*) from public.group_posts where author_id = auth.uid() and created_at > now() - interval '1 day') >= 150 then raise exception 'Daily post limit reached.'; end if;
  if p_reply is not null and not exists (select 1 from public.group_posts where id = p_reply and group_id = gid) then p_reply := null; end if;
  insert into public.group_posts(group_id, author_id, body, reply_to) values (gid, auth.uid(), b, p_reply) returning id into pid;
  return pid;
end $$;

-- three different members reporting a post hides it at once; a moderator then restores or removes it
create or replace function public.report_post(pid bigint, p_reason text) returns void language plpgsql security definer set search_path = public as $$
declare gp record; n int;
begin
  select * into gp from public.group_posts where id = pid;
  if not found or not public.in_group(gp.group_id) then raise exception 'unknown post'; end if;
  if gp.author_id = auth.uid() then raise exception 'You cannot report your own post.'; end if;
  insert into public.post_reports(post_id, reporter_id, reason) values (pid, auth.uid(), left(coalesce(nullif(trim(p_reason), ''), 'No reason given'), 300)) on conflict do nothing;
  select count(*) into n from public.post_reports where post_id = pid;
  if n >= 3 and not gp.hidden then
    update public.group_posts set hidden = true, hidden_reason = 'Hidden after reports' where id = pid;
    insert into public.mod_actions(group_id, post_id, actor_id, target_id, action) values (gp.group_id, pid, null, gp.author_id, 'auto_hide');
  end if;
end $$;

create or replace function public.moderate_post(pid bigint, p_action text) returns void language plpgsql security definer set search_path = public as $$
declare gp record;
begin
  select * into gp from public.group_posts where id = pid;
  if not found or not public.can_moderate_group(gp.group_id) then raise exception 'not allowed'; end if;
  if p_action = 'hide' then update public.group_posts set hidden = true, hidden_reason = 'Hidden by a moderator' where id = pid;
  elsif p_action = 'restore' then update public.group_posts set hidden = false, hidden_reason = null where id = pid; delete from public.post_reports where post_id = pid;
  elsif p_action = 'remove' then update public.group_posts set hidden = true, hidden_reason = 'Removed by a moderator', body = '[removed]' where id = pid;
  else raise exception 'unknown action'; end if;
  insert into public.mod_actions(group_id, post_id, actor_id, target_id, action) values (gp.group_id, pid, auth.uid(), gp.author_id, p_action);
end $$;

create or replace function public.mute_member(gid uuid, uid uuid, p_hours int) returns void language plpgsql security definer set search_path = public as $$
begin
  if not public.can_moderate_group(gid) then raise exception 'not allowed'; end if;
  if uid = auth.uid() then raise exception 'You cannot mute yourself.'; end if;
  if p_hours < 1 or p_hours > 720 then raise exception 'Mute for 1 to 720 hours.'; end if;
  update public.group_members set muted_until = now() + make_interval(hours => p_hours) where group_id = gid and user_id = uid and role = 'member';
  if not found then raise exception 'Only ordinary members can be muted.'; end if;
  insert into public.mod_actions(group_id, actor_id, target_id, action) values (gid, auth.uid(), uid, 'mute');
end $$;

create or replace function public.remove_member(gid uuid, uid uuid) returns void language plpgsql security definer set search_path = public as $$
begin
  if not public.can_moderate_group(gid) then raise exception 'not allowed'; end if;
  delete from public.group_members where group_id = gid and user_id = uid and role = 'member';
  if not found then raise exception 'Only ordinary members can be removed.'; end if;
  insert into public.mod_actions(group_id, actor_id, target_id, action) values (gid, auth.uid(), uid, 'remove_member');
end $$;

create or replace function public.archive_group(gid uuid) returns void language plpgsql security definer set search_path = public as $$
begin
  if not (public.can_moderate_group(gid) or exists (select 1 from public.study_groups where id = gid and created_by = auth.uid())) then raise exception 'not allowed'; end if;
  update public.study_groups set archived = true where id = gid;
  insert into public.mod_actions(group_id, actor_id, action) values (gid, auth.uid(), 'archive');
end $$;

-- feed and roster return display names as "First S." only
create or replace function public.group_feed(gid uuid, p_before bigint default null, p_limit int default 30)
returns table (id bigint, author_id uuid, author text, body text, reply_to bigint, hidden boolean, hidden_reason text, reports bigint, created_at timestamptz, mine boolean)
language plpgsql stable security definer set search_path = public as $$
begin
  if not (public.in_group(gid) or public.can_moderate_group(gid)) then raise exception 'not allowed'; end if;
  return query
    select gp.id, gp.author_id, p.first_name || ' ' || left(p.surname, 1) || '.', case when gp.hidden and not public.can_moderate_group(gid) then '' else gp.body end,
           gp.reply_to, gp.hidden, gp.hidden_reason,
           case when public.can_moderate_group(gid) then (select count(*) from public.post_reports r where r.post_id = gp.id) else 0 end,
           gp.created_at, gp.author_id = auth.uid()
    from public.group_posts gp join public.profiles p on p.id = gp.author_id
    where gp.group_id = gid and (p_before is null or gp.id < p_before)
      and (not gp.hidden or public.can_moderate_group(gid))
    order by gp.id desc limit least(greatest(p_limit, 1), 100);
end $$;

create or replace function public.group_roster(gid uuid)
returns table (user_id uuid, display text, role text, muted boolean, joined_at timestamptz)
language plpgsql stable security definer set search_path = public as $$
begin
  if not (public.in_group(gid) or public.can_moderate_group(gid)) then raise exception 'not allowed'; end if;
  return query select gm.user_id, p.first_name || ' ' || left(p.surname, 1) || '.', gm.role, coalesce(gm.muted_until > now(), false), gm.joined_at
    from public.group_members gm join public.profiles p on p.id = gm.user_id where gm.group_id = gid order by gm.role desc, p.first_name;
end $$;

-- my groups, and groups I could join
create or replace function public.my_groups()
returns table (id uuid, name text, description text, scope text, role text, members bigint, supervised boolean)
language sql stable security definer set search_path = public as $$
  select g.id, g.name, g.description, g.scope, gm.role, (select count(*) from public.group_members x where x.group_id = g.id),
         g.school_id is not null
  from public.group_members gm join public.study_groups g on g.id = gm.group_id and not g.archived where gm.user_id = auth.uid() order by g.name $$;
create or replace function public.discover_groups()
returns table (id uuid, name text, description text, scope text, members bigint)
language sql stable security definer set search_path = public as $$
  select g.id, g.name, g.description, g.scope, (select count(*) from public.group_members x where x.group_id = g.id)
  from public.study_groups g where public.group_eligible(g.id) and not public.in_group(g.id) order by 5 desc, g.name limit 50 $$;

-- moderation queue for staff: hidden or reported posts in groups the caller can moderate
create or replace function public.mod_queue()
returns table (post_id bigint, group_id uuid, group_name text, author text, body text, hidden boolean, reports bigint, created_at timestamptz)
language sql stable security definer set search_path = public as $$
  select gp.id, gp.group_id, g.name, p.first_name || ' ' || left(p.surname, 1) || '.', gp.body, gp.hidden,
         (select count(*) from public.post_reports r where r.post_id = gp.id), gp.created_at
  from public.group_posts gp join public.study_groups g on g.id = gp.group_id join public.profiles p on p.id = gp.author_id
  where public.can_moderate_group(gp.group_id) and (gp.hidden or exists (select 1 from public.post_reports r where r.post_id = gp.id))
    and gp.hidden_reason is distinct from 'Removed by a moderator'
  order by gp.created_at desc limit 100 $$;

do $$ declare f text; begin
  foreach f in array array['create_group(text,text,text,uuid)','join_group(uuid)','leave_group(uuid)','post_to_group(uuid,text,bigint)','report_post(bigint,text)',
    'moderate_post(bigint,text)','mute_member(uuid,uuid,int)','remove_member(uuid,uuid)','archive_group(uuid)','group_feed(uuid,bigint,int)','group_roster(uuid)',
    'my_groups()','discover_groups()','mod_queue()','in_group(uuid)','can_moderate_group(uuid)','group_eligible(uuid)'] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
end $$;

-- =====================================================================================
-- 3. Push helpers (called only by edge functions with the service role)
-- =====================================================================================
create or replace function public.due_revision_counts() returns table (user_id uuid, due bigint)
language sql stable security definer set search_path = public as $$
  select r.user_id, count(*) from public.revision_items r
  where r.done_at is null and r.due_on <= current_date and exists (select 1 from public.push_subscriptions s where s.user_id = r.user_id)
  group by r.user_id $$;
create or replace function public.staff_can_reach(p_staff uuid, p_class uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.profiles s where s.id = p_staff and (
      s.role = 'platform_admin'
      or (s.role = 'school_admin' and s.school_id = (select school_id from public.classes where id = p_class))
      or exists (select 1 from public.teacher_subjects t where t.teacher_id = p_staff and t.class_id = p_class))) $$;
revoke all on function public.due_revision_counts() from public, anon, authenticated;
revoke all on function public.staff_can_reach(uuid,uuid) from public, anon, authenticated;
grant execute on function public.due_revision_counts() to service_role;
grant execute on function public.staff_can_reach(uuid,uuid) to service_role;

-- =====================================================================================
-- 4. Student-facing helper: the teachers of my class (so a student can message them)
-- =====================================================================================
create or replace function public.my_teachers()
returns table (teacher_id uuid, first_name text, surname text, subject text)
language sql stable security definer set search_path = public as $$
  select t.teacher_id, p.first_name, p.surname, t.subject
  from public.teacher_subjects t join public.profiles p on p.id = t.teacher_id
  where t.class_id = (select class_id from public.profiles where id = auth.uid())
    and (select role from public.profiles where id = auth.uid()) = 'student'
  order by p.surname, t.subject $$;
revoke all on function public.my_teachers() from public, anon;
grant execute on function public.my_teachers() to authenticated;
